def ep(n, slug, date, title, hook, cta, scenes, sources, tie, caption, tags):
    return dict(n=n, slug=slug, date=date, title=title, hook=hook, cta=cta, scenes=scenes, sources=sources, app_tie=tie, caption=caption, tags=tags)

def sc(dur, kind, text, vo, art, src=None):
    return dict(dur=dur, kind=kind, text=text, vo=vo, art=art, **({"src": src} if src else {}))

